def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_def = 0
    my_def = 0
    my_score = 0
    opp_score = 0

    for m, o in history:
        if m == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1

        if m == 'C':
            if o == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if o == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    last_my, last_op = history[-1]

    # If the opponent has never defected, confirm that cooperation is real,
    # then exploit it for the rest of the match.
    if opp_def == 0:
        if my_def == 0:
            if n >= 70:
                return 'D'
            return 'C'
        if my_def == 1 and last_my == 'D':
            return 'C'
        return 'D'

    # Pure defector: take the safe mutual-defection payoff.
    if opp_def == n:
        return 'D'

    recent6 = history[-6:] if n >= 6 else history
    recent10 = history[-10:] if n >= 10 else history
    recent6_opp_d = sum(1 for _, o in recent6 if o == 'D')
    recent10_opp_d = sum(1 for _, o in recent10 if o == 'D')

    if last_op == 'D':
        streak = 0
        idx = n - 1
        while idx >= 0 and history[idx][1] == 'D':
            streak += 1
            idx -= 1

        start = idx + 1
        provoked = last_my == 'D' or (start > 0 and history[start - 1][0] == 'D')
        other_d = opp_def - streak

        # A short retaliation triggered by our own defection should be forgiven.
        if provoked and streak <= 4 and other_d <= max(2, n // 20):
            return 'C'

        # Broadly hostile behavior: defect consistently.
        if opp_def * 2 > n or recent10_opp_d >= 6 or recent6_opp_d >= 4:
            return 'D'

        # Unprovoked defection: punish once.
        if not provoked:
            return 'D'

        return 'C'

    # Opponent cooperated last round.
    if last_my == 'D':
        # They did not punish our defection and remain very cooperative:
        # exploit with some probability, but avoid creating long conflict chains.
        if opp_def * 5 <= n and recent6_opp_d <= 2 and rng.random() < 0.8:
            return 'D'
        return 'C'

    # Mutual cooperation. Only try a catch-up defect if clearly behind and the
    # opponent is mostly cooperative.
    if opp_score > my_score + 18 and opp_def * 3 <= n and recent6_opp_d <= 1:
        if rng.random() < 0.25:
            return 'D'

    return 'C'
